impl Month {
    fn last_day(self, year: u32) -> u32 {
        let d = match self {
            Month::February => if is_leap_year(year) { 29 } else { 28 },
            Month::April | Month::June | Month::September | Month::November => 30,
            _ => 31,
        };
        d
    }
}
